def sem(rs1, rs2, state):
    # XRQS: lam tron nua-len + dich phai so hoc + kep bao hoa int8
    # rs1: uint32 bieu dien accumulator int32 (bu hai)
    # rs2: so bit dich, lay 5 bit thap
    x = rs1 - (1 << 32) if (rs1 & 0x80000000) else rs1   # giai ma bu hai
    sh = rs2 & 0x1F
    if sh:
        x = (x + (1 << (sh - 1))) >> sh                  # dich phai so hoc, lam tron nua-len
    if x < -128:
        x = -128
    elif x > 127:
        x = 127
    return x & 0xFFFFFFFF, state                          # tra ve dang bu hai 32 bit
